args.content:
/* Halcyon Threshold — Site Styles */

:root {
    --color-bg: #fafafa;
    --color-text: #2a2a2a;
    --color-accent: #4a6fa5;
    --color-accent-light: #6989b9;
    --color-muted: #666;
    --max-width: 720px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: 'Georgia', 'Times New Roman', serif;
    font-size: 18px;
    line-height: 1.7;
    color: var(--color-text);
    background-color: var(--color-bg);
    padding: 2rem 1.5rem;
}

header, main, footer {
    max-width: var(--max-width);
    margin: 0 auto;
}

header {
    text-align: center;
    padding: 3rem 0 2rem;
    border-bottom: 1px solid #ddd;
    margin-bottom: 2.5rem;
}

h1 {
    font-size: 2.5rem;
    font-weight: normal;
    letter-spacing: 0.02em;
    margin-bottom: 0.5rem;
}

.tagline {
    font-style: italic;
    color: var(--color-muted);
    font-size: 1.1rem;
}

h2 {
    font-size: 1.4rem;
    font-weight: normal;
    color: var(--color-accent);
    margin-bottom: 1rem;
    padding-bottom: 0.3rem;
    border-bottom: 2px solid var(--color-accent);
}

section {
    margin-bottom: 2.5rem;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin: 1rem 0 1rem 1.5rem;
}

li {
    margin-bottom: 0.75rem;
}

a {
    color: var(--color-accent);
    text-decoration: none;
}

a:hover {
    color: var(--color-accent-light);
    text-decoration: underline;
}

footer {
    margin-top: 4rem;
    padding-top: 2rem;
    border-top: 1px solid #ddd;
    text-align: center;
    color: var(--color-muted);
    font-size: 0.9rem;
}

@media (max-width: 600px) {
    body {
        font-size: 16px;
        padding: 1rem;
    }

    h1 {
        font-size: 2rem;
    }

    header {
        padding: 2rem 0 1.5rem;
    }
}
